<template><div><el-input v-model="search" class="search" clearable placeholder="搜索申请门店、员工或备注"/><el-table :data="filtered" row-key="id"><el-table-column type="expand"><template #default="{row}"><div class="details"><p>备注：{{row.remark||'未填写'}}；支援不改变员工原归属、岗位和薪资。</p><el-table :data="row.people"><el-table-column label="人员" min-width="180"><template #default="{row:p}">{{p.name}}（{{p.position}}）</template></el-table-column><el-table-column label="人员来源" min-width="180"><template #default="{row:p}">{{p.source_type==='group'?'集团人员':p.source_store_name}}</template></el-table-column><el-table-column label="审批方式" width="120"><template #default="{row:p}">{{p.source_type==='group'?'本人确认':'来源店长审批'}}</template></el-table-column><el-table-column label="结果" width="110"><template #default="{row:p}">{{personLabels[p.status]}}</template></el-table-column><el-table-column label="处理时间" min-width="170"><template #default="{row:p}">{{time(p.decided_at)}}</template></el-table-column><el-table-column prop="note" label="处理意见"/></el-table></div></template></el-table-column><el-table-column prop="store_name" label="申请门店" min-width="190"/><el-table-column prop="created_name" label="申请人" width="120"/><el-table-column label="申请时间" min-width="175"><template #default="{row}">{{time(row.created_at)}}</template></el-table-column><el-table-column label="支援时间段" min-width="210"><template #default="{row}">{{row.start_date}} 至 {{row.end_date}}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}">{{labels[row.status]}}</template></el-table-column><el-table-column label="可见人员" width="100"><template #default="{row}">{{row.people.length}} 人</template></el-table-column></el-table><p class="hint">后台仅查询申请过程与结果；确认、审批在手机上完成。</p></div></template>
<script setup>
import {ref,computed} from 'vue'
const props=defineProps({rows:{type:Array,default:()=>[]}}),search=ref(''),labels={pending:'审批中',approved:'全部同意',partial:'部分同意',rejected:'未同意',cancelled:'已撤回'},personLabels={pending:'待确认',approved:'已同意',rejected:'未同意',cancelled:'已撤回'}
const filtered=computed(()=>props.rows.filter(r=>[r.store_name,r.created_name,r.remark,...r.people.map(p=>p.name)].join(' ').includes(search.value))),time=v=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—'
</script><style scoped>.search{max-width:360px;margin:16px 0}.details{padding:16px 30px}.details p,.hint{font-size:12px;color:#8795a3;line-height:1.8}</style>
